export function normalizeTheme(t={}){if(!t||typeof t!=='object'||Array.isArray(t))t={};const base=THEMES.find(x=>x.id===t.id)||THEMES[0];const hex=v=>typeof v==='string'&&/^#[0-9a-f]{6}$/i.test(v);const fonts=FONTS.map(f=>f[0]),n=(v,min,max,d)=>{const x=Number(v);return Number.isFinite(x)?Math.max(min,Math.min(max,Math.round(x))):d};return {...base,...Object.fromEntries(['accent','accent2','bg','surface','ink','muted'].filter(k=>hex(t[k])).map(k=>[k,t[k]])),accent2:hex(t.accent2)?t.accent2:base.accent2||base.accent,font:fonts.includes(t.font)?t.font:base.font,headingFont:t.headingFont==='same'||fonts.includes(t.headingFont)?t.headingFont:base.headingFont||'same',radius:Math.max(0,Math.min(40,Number(t.radius)||0)),space:Math.max(24,Math.min(120,Number(t.space)||64)),style:STYLES.some(x=>x[0]===t.style)?t.style:base.style,headingScale:n(t.headingScale,70,150,base.headingScale||100),weight:n(t.weight,300,800,base.weight||600)};}
