export const DEMO_JS=String.raw`
(()=>{let timer;const toast=(message)=>{const el=document.querySelector('.demo-toast');if(!el)return;el.textContent=message;el.classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('visible'),2700)};
document.addEventListener('submit',e=>{if(!e.target.matches('[data-demo-form]'))return;e.preventDefault();toast('演示提交成功。数据仅在此页面使用，未发送或保存。');e.target.reset()});
const counts=()=>document.querySelectorAll('.kanban-column').forEach(c=>{c.querySelector('[data-count]').textContent=c.querySelectorAll('.task').length});counts();
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;
if(el.matches('[data-demo]'))toast('已触发「'+el.textContent.trim()+'」演示。请在实际项目中接入你的业务逻辑。');
if(el.matches('[data-nav-link]')){const dest=document.querySelector('.block-contact');e.preventDefault();if(dest)dest.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});else toast('导航演示：在拼装台添加联系表单，或在源码中设置链接。')}
if(el.matches('.mobile-menu')){const links=el.closest('nav').querySelector('.nav-links');const open=links.classList.toggle('expanded');el.setAttribute('aria-expanded',open);el.textContent=open?'×':'☰'}
if(el.matches('[data-period]')){const block=el.closest('section');block.querySelectorAll('[data-period]').forEach(x=>x.classList.toggle('active',x===el));block.querySelectorAll('[data-price]').forEach(x=>{x.textContent='¥'+Math.round(Number(x.dataset.price)*(el.dataset.period==='year'?.8:1))})}
if(el.matches('[data-task-next]')){const c=el.closest('.kanban-column'),board=c.parentElement;const next=board.querySelector('[data-stage="'+((Number(c.dataset.stage)+1)%3)+'"]');next.append(el.closest('.task'));counts()}
if(el.matches('[data-task-add]')){const board=el.closest('section').querySelector('.kanban');if(board.querySelectorAll('.task').length>=30){toast('演示任务已达上限');return}const c=board.querySelector('[data-stage="0"]');const task=document.createElement('article');task.className='task';task.innerHTML='<span class="tag">新想法</span><h4>一个新的创作任务</h4><div><small>◎ 今天</small><button type="button" data-task-next aria-label="移动任务到下一列">→</button></div>';c.append(task);counts();toast('新的演示任务已添加')}
if(el.matches('.tabs-panel [role="tab"]')){const panel=el.closest('.tabs-panel');panel.querySelectorAll('[role="tab"]').forEach(t=>{t.setAttribute('aria-selected',t===el);t.tabIndex=t===el?0:-1});panel.querySelectorAll('[role="tabpanel"]').forEach(p=>p.hidden=p.id!==el.getAttribute('aria-controls'))}
if(el.matches('[data-like]')){const liked=el.getAttribute('aria-pressed')!=='true';el.setAttribute('aria-pressed',liked);el.textContent=liked?'♥':'♡'}
if(el.matches('[data-loading]')){el.disabled=true;el.textContent='正在准备…';setTimeout(()=>{el.disabled=false;el.textContent='再试一次 ↗';toast('加载演示完成')},900)}
if(el.matches('[data-swatch]')){const block=el.closest('section');block.querySelectorAll('[data-swatch]').forEach(x=>x.setAttribute('aria-pressed',x===el));block.querySelector('.lamp').style.setProperty('--lamp-color',el.style.getPropertyValue('--swatch'))}
if(el.matches('[data-gallery-filter]')){const block=el.closest('section'),n=el.dataset.galleryFilter;block.querySelectorAll('[data-gallery-filter]').forEach(x=>{x.classList.toggle('active',x===el);x.setAttribute('aria-pressed',x===el)});block.querySelectorAll('[data-work-category]').forEach(x=>x.hidden=n!=='0'&&x.dataset.workCategory!==n)}
if(el.matches('[data-step-next],[data-step-back]')){const p=el.closest('[data-step-panel]');let n=Number(p.dataset.step)+(el.matches('[data-step-next]')?1:-1);if(n>2){toast('演示流程已完成。你的新旅程就要开始。');n=0}n=Math.max(0,n);p.dataset.step=n;p.querySelectorAll('.steps>span').forEach((x,i)=>x.classList.toggle('current',i===n));p.querySelector('[data-step-back]').disabled=n===0;p.querySelector('[data-step-next]').textContent=n===2?'完成演示 ✓':'下一步 →';p.querySelector('[data-step-title]').textContent=['先打个招呼。','找到你的方向。','准备好，出发。'][n];p.querySelector('[data-step-copy]').textContent=['每个好项目，都是从相互认识开始的。','选择让你感兴趣的问题，试着走出第一步。','把好奇心装进口袋，新的故事即将开始。'][n]}
});
document.addEventListener('keydown',e=>{if(e.target.matches('.tabs-panel [role="tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...e.target.parentElement.querySelectorAll('[role="tab"]')];let n=tabs.indexOf(e.target);n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(n+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].click();tabs[n].focus()}});
document.addEventListener('input',e=>{if(e.target.matches('[data-command-search]')){const panel=e.target.closest('.command-panel'),q=e.target.value.toLowerCase();let n=0;panel.querySelectorAll('[data-command-item]').forEach(x=>{x.hidden=!x.textContent.toLowerCase().includes(q);if(!x.hidden)n++});panel.querySelector('[data-command-empty]').hidden=n>0}});
})();`;
